/// Appends `n` elements built from `n` slot records of 12 u64 each (mask
/// word(s), then one slot per leaf), or `n` defaults when `slots` is null.
/// Returns the first new element's key: its packed ref on a refs::Vec,
/// its index on a std::vec::Vec.
#[no_mangle]
pub unsafe extern "C" fn ba_problem_poses_push_n(p: *mut BaProblemHandle, slots: *const u64, n: u32) -> u32 {
    let m = &mut (*p).model.poses;
    let first = m.len();
    m.reserve(n as usize);
    for i in 0..n as usize {
        let mut e: Pose = Default::default();
        if !slots.is_null() {
            assign_slots_pose(&mut e, slots.add(i * 12));
        }
        m.push(e);
    }
    if n == 0 { u32::MAX } else { m.ref_at(first).to_raw() }
}
/// Sets `rot` on elements `start..start + n` from values `stride` bytes
/// apart (0 broadcasts one value); false when the range exceeds the collection.
#[no_mangle]
pub unsafe extern "C" fn ba_problem_poses_set_rot_n(
    p: *mut BaProblemHandle, start: u32, v: *const f64, n: u32, stride: i64) -> bool {
    let m = &mut (*p).model.poses;
    let (start, n) = (start as usize, n as usize);
    if start + n > m.len() {
        return false;
    }
    for i in 0..n {
        let src = (v as *const u8).offset((i as i64 * stride) as isize) as *const f64;
        m[start + i].rot.value = std::mem::transmute::<[f64; 4], CQuatF64>(std::ptr::read_unaligned(src as *const [f64; 4])).into();
    }
    true
}
