pub unsafe extern "C" fn ba_problem_cams_try_get(p: *mut BaProblemHandle, r: u32) -> *mut Cam {
    let m = &mut (*p).model.cams;
    match m.get_mut(arael::refs::Ref::from_raw(r)) {
        Some(e) => e as *mut Cam,
        None => std::ptr::null_mut(),
    }
}
/// Appends `n` elements built from `n` slot records of 33 u64 each (mask
/// word(s), then one slot per leaf), or `n` defaults when `slots` is null.
/// Returns the first new element's key: its packed ref on a refs::Vec,
/// its index on a std::vec::Vec.
#[no_mangle]
pub unsafe extern "C" fn ba_problem_cams_push_n(p: *mut BaProblemHandle, slots: *const u64, n: u32) -> u32 {
    let m = &mut (*p).model.cams;
    let first = m.len();
    m.reserve(n as usize);
    for i in 0..n as usize {
        let mut e: Cam = Default::default();
        if !slots.is_null() {
            assign_slots_cam(&mut e, slots.add(i * 33));
        }
        m.push(e);
    }
    if n == 0 { u32::MAX } else { m.ref_at(first).to_raw() }
}
/// Sets `model` on elements `start..start + n` from values `stride` bytes
/// apart (0 broadcasts one value); false when the range exceeds the collection.
#[no_mangle]
pub unsafe extern "C" fn ba_problem_cams_set_model_n(
    p: *mut BaProblemHandle, start: u32, v: *const u32, n: u32, stride: i64) -> bool {
    let m = &mut (*p).model.cams;
    let (start, n) = (start as usize, n as usize);
    if start + n > m.len() {
        return false;
    }
    for i in 0..n {
        let src = (v as *const u8).offset((i as i64 * stride) as isize) as *const u32;
        m[start + i].model = std::ptr::read_unaligned(src);
    }
    true
}
