/// Appends `n` elements built from `n` slot records of 4 u64 each (mask
/// word(s), then one slot per leaf), or `n` defaults when `slots` is null.
/// Returns the first new element's key: its packed ref on a refs::Vec,
/// its index on a std::vec::Vec.
#[no_mangle]
pub unsafe extern "C" fn ba_problem_fixed_image_obs_push_n(p: *mut FixedImage, slots: *const u64, n: u32) -> u32 {
    let m = &mut (*p).obs;
    let first = m.len();
    m.reserve(n as usize);
    for i in 0..n as usize {
        let mut e: FixedObservation = Default::default();
        if !slots.is_null() {
            assign_slots_fixed_observation(&mut e, slots.add(i * 4));
        }
        m.push(e);
    }
    first as u32
}
